const pons={sequenceId:'brainstem',conceptId:'brainstem-pons'},saved=createHeadLearningBookmark(pons);localStorage.setItem(HEAD_LEARNING_BOOKMARK_KEY,JSON.stringify(saved));const params=new URLSearchParams(location.search),modality=params.get('view');const isScan=modality==='CT'||modality==='MRI';
