fs.writeFileSync(out+'/index.html','<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Isolated saved-step QA</title><link rel="stylesheet" href="bundle.css"><style>body{margin:32px;font:16px Arial,sans-serif;background:#f5faf8;color:#17352f}main{max-width:900px;margin:auto}button,a{padding:10px}a{display:inline-block;color:#075e53}</style></head><body><main id="root"></main><script src="bundle.js"></script></body></html>');
